#include <stdio.h>
#include <stdlib.h>

#define MAXE 10005
#define MAXR 20005
#define MAXA (2 * MAXR + 5)

static int head[MAXE], to[MAXA], next_edge[MAXA], edge_id[MAXA];
static int edge_u[MAXR], edge_v[MAXR], edge_w[MAXR];
static int tin[MAXE], low[MAXE], timer;
static char is_bridge[MAXR];

static int parent_set[MAXE], rank_set[MAXE];
static long long component_sum[MAXE], cycle_perimeter[MAXE];

static void add_edge(int u, int v, int id, int *arc_count) {
    to[*arc_count] = v;
    edge_id[*arc_count] = id;
    next_edge[*arc_count] = head[u];
    head[u] = (*arc_count)++;
}

static void dfs_bridges(int u, int parent_edge) {
    tin[u] = low[u] = ++timer;

    for (int arc = head[u]; arc != -1; arc = next_edge[arc]) {
        int id = edge_id[arc];
        int v = to[arc];

        if (id == parent_edge) continue;

        if (tin[v]) {
            if (tin[v] < low[u]) low[u] = tin[v];
        } else {
            dfs_bridges(v, id);
            if (low[v] < low[u]) low[u] = low[v];
            if (low[v] > tin[u]) is_bridge[id] = 1;
        }
    }
}

static int find_set(int x) {
    if (parent_set[x] != x) parent_set[x] = find_set(parent_set[x]);
    return parent_set[x];
}

static void union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a == b) return;

    if (rank_set[a] < rank_set[b]) {
        int temp = a;
        a = b;
        b = temp;
    }
    parent_set[b] = a;
    if (rank_set[a] == rank_set[b]) rank_set[a]++;
}

typedef struct {
    long long distance;
    int vertex;
} HeapNode;

typedef struct {
    HeapNode *data;
    int size;
    int capacity;
} MinHeap;

static void heap_push(MinHeap *heap, long long distance, int vertex) {
    if (heap->size == heap->capacity) {
        heap->capacity = heap->capacity ? heap->capacity * 2 : 16;
        heap->data = realloc(heap->data, (size_t)heap->capacity * sizeof(HeapNode));
    }

    int i = heap->size++;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap->data[parent].distance <= distance) break;
        heap->data[i] = heap->data[parent];
        i = parent;
    }
    heap->data[i].distance = distance;
    heap->data[i].vertex = vertex;
}

static HeapNode heap_pop(MinHeap *heap) {
    HeapNode result = heap->data[0];
    HeapNode last = heap->data[--heap->size];

    if (heap->size > 0) {
        int i = 0;
        while (2 * i + 1 < heap->size) {
            int child = 2 * i + 1;
            if (child + 1 < heap->size &&
                heap->data[child + 1].distance < heap->data[child].distance) {
                child++;
            }
            if (heap->data[child].distance >= last.distance) break;
            heap->data[i] = heap->data[child];
            i = child;
        }
        heap->data[i] = last;
    }
    return result;
}

