    int E, R;
    if (scanf("%d %d", &E, &R) != 2) return 0;

    for (int i = 1; i <= E; i++) head[i] = -1;

    int arc_count = 0;
    for (int id = 0; id < R; id++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        edge_u[id] = a;
        edge_v[id] = b;
        edge_w[id] = c;
        add_edge(a, b, id, &arc_count);
        add_edge(b, a, id, &arc_count);
    }

    for (int i = 1; i <= E; i++) {
        if (!tin[i]) dfs_bridges(i, -1);
    }

    for (int i = 1; i <= E; i++) {
        parent_set[i] = i;
        rank_set[i] = 0;
    }

    for (int id = 0; id < R; id++) {
        if (!is_bridge[id]) {
            union_sets(edge_u[id], edge_v[id]);
        }
    }

    for (int id = 0; id < R; id++) {
        if (!is_bridge[id]) {
            int root = find_set(edge_u[id]);
            component_sum[root] += edge_w[id];
        }
    }

    for (int v = 1; v <= E; v++) {
        int has_cycle_edge = 0;
        for (int arc = head[v]; arc != -1; arc = next_edge[arc]) {
            if (!is_bridge[edge_id[arc]]) {
                has_cycle_edge = 1;
                break;
            }
        }
        if (has_cycle_edge) {
            cycle_perimeter[v] = component_sum[find_set(v)];
        }
    }

    int K;
    scanf("%d", &K);

    long long *dist = malloc((size_t)(E + 1) * sizeof(long long));
    const long long INF = 0x3f3f3f3f3f3f3f3fLL;

    for (int query = 0; query < K; query++) {
        int X, T;
        scanf("%d %d", &X, &T);

        for (int v = 1; v <= E; v++) dist[v] = INF;

        MinHeap heap = {NULL, 0, 0};

        for (int v = 1; v <= E; v++) {
            if (cycle_perimeter[v] >= T) {
                dist[v] = cycle_perimeter[v];
                heap_push(&heap, dist[v], v);
            }
        }

        while (heap.size > 0) {
            HeapNode current = heap_pop(&heap);
            int u = current.vertex;
            if (current.distance != dist[u]) continue;

            for (int arc = head[u]; arc != -1; arc = next_edge[arc]) {
                int v = to[arc];
                long long candidate = current.distance + 2LL * edge_w[edge_id[arc]];
                if (candidate < dist[v]) {
                    dist[v] = candidate;
                    heap_push(&heap, candidate, v);
                }
            }
        }

        printf("%lld\n", dist[X] == INF ? -1LL : dist[X]);
        free(heap.data);
    }

    free(dist);
    return 0;
}
